package com.hmdp.ai.infrastructure.mcp;import com.hmdp.ai.domain.mcp.*;import org.springframework.stereotype.Component;@Component public class DefaultMcpManagementAdapter implements McpManagementPort {private final McpHealthService health;private final McpToolSyncService sync;public DefaultMcpManagementAdapter(McpHealthService health,McpToolSyncService sync){this.health=health;this.sync=sync;}public String checkHealth(McpServer server){return health.check(server);}public int syncTools(McpServer server,String actorId){return sync.sync(server,actorId);}}
